{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE maplemonk.Flipkart_Plaeto_order_fulfilment_fact_items AS SELECT CAST(order_date AS DATETIME) AS order_date, CAST(NULLIF(REPLACE(order_approval_date, \'\"\', \'\'), \'\') AS DATETIME) AS order_approval_date, REPLACE(REPLACE(sku, \'\"\', \'\'), \'sku:\', \'\') AS sku, order_id AS reference_code, order_id, CAST(NULLIF(order_cancellation_date, \'\') AS DATETIME) AS cancellation_date, REPLACE(cancellation_reason, \'_\', \' \') AS cancellation_reason, CAST(NULLIF(order_ready_for_dispatch_on_date, \'\') AS DATETIME) AS order_ready_for_dispatch_on_date, CAST(NULLIF(dispatch_after_date, \'\') AS DATETIME) AS manifest_date, CAST(NULLIF(dispatch_by_date, \'\') AS DATETIME) AS dispatch_date, CASE WHEN deliver_by_date = \'N\' THEN NULL ELSE SAFE_CAST(deliver_by_date AS DATE) END AS delivery_date, CASE WHEN UPPER(pickup_logistics_partner) LIKE \'%COD%\' THEN \'cod\' ELSE \'prepaid\' END AS payment_mode, pickup_logistics_partner AS courier, CAST(NULLIF(order_return_approval_date, \'\') AS DATETIME) AS return_approval_date, CAST(NULLIF(order_service_completion_date, \'\') AS DATETIME) AS order_service_completion_date, return_id, REPLACE(return_reason, \'_\', \' \') AS return_reason, REPLACE(return_sub_reason, \'_\', \' \') AS return_sub_reason, REPLACE(order_item_id, \'OI:\', \'\') AS order_item_id, REPLACE(product_title, \'\"\', \'\') AS product_name, fulfilment_type, fulfilment_source, REPLACE(order_item_status, \'_\', \' \') AS order_item_status, REPLACE(delivery_tracking_id, \'DTr:\', \'\') AS fk_awb FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id, order_item_id ORDER BY order_return_approval_date DESC) AS rn FROM maplemonk.Plaeto_fk_orders ) x WHERE rn = 1; CREATE OR REPLACE TABLE maplemonk.Flipkart_Plaeto_fact_items AS SELECT CASE WHEN s.`Fulfilment_Type` = \'NON_FBF\' THEN \'Flipkart NON-FBF\' ELSE \'Flipkart FBF\' END AS shop_name, s.order_id, s.order_id AS order_name, NULL AS customer_id, NULL AS phone, s.`hsn_code` AS HSN_Code, s.`order_type` AS payment_type, CAST(NULL AS STRING) AS tags, s.`order_item_id` AS line_item_id, CAST(REPLACE(REPLACE(s.sku, \'\"\', \'\'), \'SKU:\', \'\') AS STRING) AS SKU, REPLACE(s.FSN, \'\"\', \'\') AS product_id, CASE WHEN r.`Event_Sub_Type` = \'Return\' THEN 1 ELSE 0 END AS is_refund, CAST(null AS STRING) AS city, UPPER(COALESCE(CASE WHEN s.customer_s_delivery_pincode = \'-\' THEN (CASE WHEN s.customer_s_billing_state = \'-\' THEN NULL ELSE s.`customer_s_billing_state` END) ELSE s.`customer_s_delivery_state` END)) AS state, CASE WHEN s.customer_s_delivery_pincode = \'-\' THEN (CASE WHEN s.customer_s_billing_pincode = \'-\' THEN NULL ELSE s.customer_s_billing_pincode END) ELSE s.customer_s_delivery_pincode END AS pincode, REPLACE(s.product_title_description, \'\"\', \'\') AS PRODUCT_NAME, UPPER(COALESCE(p.category)) AS category, UPPER(COALESCE(p.product_name)) AS product_name_final, UPPER(COALESCE(p.commonsku)) AS commonsku, UPPER(coalesce(category_gender)) PRODUCT_CATEGORY_GENDER, CASE WHEN NOT(s.`order_date` = \'-\') THEN CAST(SUBSTR(s.`order_date`, 1, 19) AS DATETIME) END AS order_date, f.delivery_date, f.cancellation_date, f.manifest_date, f.dispatch_date, f.return_approval_date, f.return_reason, f.return_sub_reason, f.order_service_completion_date, f.order_item_status, f.return_id, f.fulfilment_type, f.fulfilment_source, f.cancellation_reason, f.payment_mode, CASE WHEN REGEXP_CONTAINS(s.`tds_rate`, r\'^[+-]?[0-9]+(\.[0-9]+)?$\') THEN CAST(s.`tds_rate` AS FLOAT64) ELSE NULL END AS tds_rate, CASE WHEN REGEXP_CONTAINS(s.`VAT_Rate`, r\'^[+-]?[0-9]+(\.[0-9]+)?$\') THEN CAST(s.`VAT_Rate` AS FLOAT64) ELSE NULL END AS VAT_Rate, CASE WHEN REGEXP_CONTAINS(s.`CGST_Rate`, r\'^[+-]?[0-9]+(\.[0-9]+)?$\') THEN CAST(s.`CGST_Rate` AS FLOAT64) ELSE NULL END AS CGST_Rate, CASE WHEN REGEXP_CONTAINS(s.`IGST_Rate`, r\'^[+-]?[0-9]+(\.[0-9]+)?$\') THEN CAST(s.`IGST_Rate` AS FLOAT64) ELSE NULL END AS IGST_Rate, CASE WHEN REGEXP_CONTAINS(s.`CST_Amount`, r\'^[+-]?[0-9]+(\.[0-9]+)?$\') THEN CAST(s.`CST_Amount` AS FLOAT64) ELSE NULL END AS CST_Amount, CASE WHEN REGEXP_CONTAINS(s.`TDS_Amount`, r\'^[+-]?[0-9]+(\.[0-9]+)?$\') THEN CAST(s.`TDS_Amount` AS FLOAT64) ELSE NULL END AS TDS_Amount, CASE WHEN REGEXP_CONTAINS(s.`VAT_Amount`, r\'^[+-]?[0-9]+(\.[0-9]+)?$\') THEN CAST(s.`VAT_Amount` AS FLOAT64) ELSE NULL END AS VAT_Amount, CASE WHEN REGEXP_CONTAINS(s.`CGST_Amount`, r\'^[+-]?[0-9]+(\.[0-9]+)?$\') THEN CAST(s.`CGST_Amount` AS FLOAT64) ELSE NULL END AS CGST_Amount, CASE WHEN REGEXP_CONTAINS(s.`IGST_Amount`, r\'^[+-]?[0-9]+(\.[0-9]+)?$\') THEN CAST(s.`IGST_Amount` AS FLOAT64) ELSE NULL END AS IGST_Amount, CASE WHEN REGEXP_CONTAINS(s.`Type_of_tax`, r\'^-?\d+(\.\d+)?$\') THEN CAST(s.`Type_of_tax` AS FLOAT64) ELSE NULL END AS Type_of_tax, CASE WHEN s.`Usual_Price` = \'NA\' THEN NULL WHEN REGEXP_CONTAINS(s.`Usual_Price`, r\'^[+-]?[0-9]+(\.[0-9]+)?$\') THEN CAST(s.`Usual_Price` AS FLOAT64) ELSE NULL END AS Usual_Price, s.`Seller_GSTIN`, ABS(COALESCE(CASE WHEN REGEXP_CONTAINS(s.`price_after_discount__price_before_discount_total_discount_`, r\'^[+-]?[0-9]+(\.[0-9]+)?$\') THEN CAST(s.`price_after_discount__price_before_discount_total_discount_` AS FLOAT64) ELSE 0 END, 0)) AS line_item_sales, ABS(COALESCE(CASE WHEN REGEXP_CONTAINS(s.`Shipping_Charges`, r\'^[+-]?[0-9]+(\.[0-9]+)?$\') THEN CAST(s.`Shipping_Charges` AS FLOAT64) ELSE 0 END, 0)) AS shipping_price, ABS(COALESCE(CASE WHEN REGEXP_CONTAINS(s.`Item_Quantity`, r\'^[+-]?[0-9]+(\.[0-9]+)?$\') THEN CAST(s.`Item_Quantity` AS FLOAT64) ELSE 0 END, 0)) AS quantity, ABS(COALESCE(CASE WHEN REGEXP_CONTAINS(s.`Total_TCS_Deducted`, r\'^[+-]?[0-9]+(\.[0-9]+)?$\') THEN CAST(s.`Total_TCS_Deducted` AS FLOAT64) ELSE 0 END, 0)) AS tax, ABS(COALESCE(SAFE_CAST(s.`price_after_discount__price_before_discount_total_discount_` AS FLOAT64), 0)) / NULLIF(COALESCE(SAFE_CAST(s.`price_after_discount__price_before_discount_total_discount_` AS FLOAT64), 0) + COALESCE(SAFE_CAST(s.`Total_TCS_Deducted` AS FLOAT64), 0), 0) AS overall_tax_rate, ABS(COALESCE(SAFE_CAST(s.`Total_Discount` AS FLOAT64), 0)) AS discount, CASE WHEN LOWER(s.`is_shopsy_order_`) IN (\'true\', \'1\', \'yes\', \'y\') THEN \'Shopsy Order\' ELSE \'Flipkart Order\' END AS Order_Channel, s.`Beneficiary_Name` AS name, CAST(NULL AS STRING) AS email, f.fk_awb AS awb, f.courier, s.`order_shipped_from__state_` AS Order_Shipped_From_State, s.`Warehouse_ID`, s.`Business_Name` FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY `order_item_id`, `order_id` ORDER BY `buyer_invoice_id` DESC) AS rn FROM maplemonk.Plaeto_fk_sales WHERE LOWER(`Event_Sub_Type`) LIKE \'%sale%\' ) s LEFT JOIN maplemonk.Flipkart_Plaeto_order_fulfilment_fact_items f ON f.order_id = s.`order_id` AND f.order_item_id = s.`order_item_id` LEFT JOIN ( SELECT *, ROW_NUMBER() OVER (PARTITION BY `order_item_id`, `order_id` ORDER BY `buyer_invoice_id` DESC) AS rn FROM maplemonk.Plaeto_fk_sales WHERE LOWER(`Event_Sub_Type`) LIKE \'%return%\' ) r ON r.`order_id` = s.`order_id` AND r.`order_item_id` = s.`order_item_id` left join (select * from ( select master_sku as skucode, master_sku commonsku, colour_code, style_code, product_code, category_gender, style_name, sub_style_name, product_name, outsole_colour, category, size, size_band, Colour, Colour_2, fob, mrp, row_number() over (partition by lower(replace(master_sku,\' \',\'\')) order by 1) rw from plaeup-wh.maplemonk.Final_SKU_master ) where rw = 1 ) p on lower(cast(replace(replace(s.sku,\'\"\',\'\'),\'SKU:\',\'\') as string)) = lower(replace(p.skucode,\' \',\'\'));",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            